Here's a Python script that does this:

```python
class VariableManager:
    def __init__(self):
        self.variables = {}

    def assign(self, target, source):
        if source in self.variables:
            self.variables[target] = self.variables[source]
        else:
            self.variables[target] = int(source)

    def get_value(self, var_name):
        return self.variables.get(var_name, None)

def process_lines(lines, vm):
    for line in lines:
        parts = line.split()
        if len(parts) > 2 and parts[1] == '=':
            target = parts[0]
            source = parts[2]
            vm.assign(target, source)

def main():
    # Example lines of code
    lines = [
        "VAR X = 14673",
        "VAR A = 10",
        "VAR B = VAR A",
        "VAR C = 14673"
    ]

    vm = VariableManager()
    process_lines(lines, vm)

    # Check the values of all variables at the end
    for var_name, value in vm.variables.items():
        if value == 14673:
            print(var_name)

    print("Answer:", ", ".join(vm.variables.keys()))

if __name__ == "__main__":
    main()
